import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';

/**
 * Decodes an embedded (base64-in-JS) GLTF/GLB into a THREE.Group.
 *
 * Takes the exports from a module generated by tools/embed-asset.mjs, e.g.:
 *
 *   import { crowdMascotData, crowdMascotMime } from './embedded/crowdMascot.embed.js';
 *   const mascot = await loadEmbeddedModel(crowdMascotData);
 *   scene.add(mascot);
 *
 * Never pass a URL here — GLTFLoader.load() fetches, and fetch() from a
 * file:// build to a separate file:// asset is blocked by Chrome. parse()
 * on an in-memory ArrayBuffer has no such restriction, which is the entire
 * point of embedding rather than referencing.
 */
const loader = new GLTFLoader();

function base64ToArrayBuffer(base64) {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes.buffer;
}

export function loadEmbeddedModel(base64Data) {
  return new Promise((resolve, reject) => {
    loader.parse(
      base64ToArrayBuffer(base64Data),
      '',
      (gltf) => resolve(gltf.scene),
      (err) => reject(err)
    );
  });
}
